// Ported from the prototype at tag add7b-e540f8ae4d6b (src/how/RepresentativeOutput.jsx).
import { useMemo, useState } from 'react'
// Every byte below is SYNTHETIC: generated by how-sample.mjs from src/how/entries.json with the real
// tools (scrubbed tar → gzip -n → age X25519 → tle to drand quicknet via Tor → armored). No vault was read.
import SEALED from './data/sealed-sample.txt?raw'
import LISTING from './data/archive-listing.txt?raw'
import MANIFEST from './data/manifest-sample.csv?raw'
import ATTACH from './data/attachments-sample.csv?raw'

const csv = (t) => t.trim().split('\n').slice(1).map((l) => l.split(','))

// Split SEALED.txt into labelled segments so each part can be coloured and explained.
function segments(text) {
  const lines = text.replace(/\n$/, '').split('\n')
  const out = []
  let cur = null
  const push = (kind, label) => { cur = { kind, label, lines: [] }; out.push(cur) }
  for (const l of lines) {
    if (l.startsWith('== vault-timelock sealed')) push('prefix', 'prefix: what this is, layers, unlock time, drand, tools')
    else if (l.startsWith('open after unlock-after')) push('steps', 'how to decrypt: literal steps')
    else if (l.startsWith('notes:')) push('notes', 'honest limits')
    else if (l.startsWith('[file unlock-TIME.age')) push('time', 'unlock-TIME.age: the data key, time-locked to drand round R')
    else if (l.startsWith('[file vault.tar.gz.age')) push('vault', 'vault.tar.gz.age: ALL entries, encrypted once with the data key')
    else if (l.startsWith('== end')) push('end', 'end')
    cur.lines.push(l)
  }
  return out
}

const KIND = {
  prefix: 'border-sky-500/60 bg-sky-500/5 text-sky-200',
  steps: 'border-neutral-600 bg-neutral-900 text-neutral-200',
  notes: 'border-neutral-600 bg-neutral-900 text-neutral-300',
  time: 'border-violet-500/60 bg-violet-500/5 text-violet-200',
  vault: 'border-emerald-500/60 bg-emerald-500/5 text-emerald-200',
  end: 'border-neutral-700 text-neutral-400',
}

function ArmorBlock({ lines, full }) {
  // first line is the [file …] line; then BEGIN … END
  const head = lines.slice(0, 1), body = lines.slice(1)
  const begin = body.findIndex((l) => l.startsWith('-----BEGIN')), end = body.findIndex((l) => l.startsWith('-----END'))
  const b64 = body.slice(begin + 1, end)
  const shown = full ? b64 : [...b64.slice(0, 2), `  … ${b64.length - 3} more 64-column lines …`, ...b64.slice(-1)]
  return [...head, body[begin], ...shown, body[end]].join('\n')
}

export function RepresentativeOutput({ entries, sel, setSel, digests }) {
  const [full, setFull] = useState(false)
  const segs = useMemo(() => segments(SEALED), [])
  const man = useMemo(() => Object.fromEntries(csv(MANIFEST).map((r) => [r[0], r])), [])
  const att = useMemo(() => csv(ATTACH), [])
  const e = entries.find((x) => x.id === sel) || entries[0]
  const digest = digests[e.id]
  const manRow = man[e.uuid]
  const listing = LISTING.trim().split('\n')
  const bytes = new TextEncoder().encode(SEALED).length

  return (
    <section className="mt-6 rounded-xl border border-neutral-800 bg-neutral-950 p-4">
      <h2 className="text-base font-semibold">Representative output: plaintext entries → the published, self-contained payload</h2>
      <p className="mb-3 text-sm text-neutral-400">
        The four <b>synthetic</b> entries below are in the plaintext form <span className="font-mono">op item get --reveal</span> produces.
        They were sealed with the real tools into the payload on the right ({bytes.toLocaleString()} B, ASCII only). Click an entry to follow it.
      </p>

      <div className="flex flex-col gap-3">
        {/* 1. entries in plaintext form */}
        <div>
          <div className="mb-2 text-xs font-bold uppercase tracking-wider text-neutral-300">1 · Entries, plaintext form</div>
          <div className="mb-2 flex flex-wrap gap-2">
            {entries.map((x) => (
              <button key={x.id} onClick={() => setSel(x.id)}
                className={`rounded-md border px-2 py-1 text-xs ${x.id === e.id ? 'border-amber-400 text-amber-300' : 'border-neutral-700 text-neutral-300 hover:bg-neutral-800'}`}>
                {x.id} · {x.cat}{x.files ? ' · 1 file' : ''}{x.blank ? ' · blank pw' : ''}
              </button>
            ))}
          </div>
          <div className="rounded-lg border border-amber-500/60 bg-amber-500/5 p-2">
            <div className="mb-1 flex items-center justify-between text-xs">
              <span className="font-mono text-amber-300">items/{e.uuid}.json</span>
              <span className="text-amber-200/70">plaintext · only inside the seal</span>
            </div>
            <pre className="max-h-72 overflow-auto whitespace-pre-wrap break-all font-mono text-[11px] leading-4 text-amber-100">{JSON.stringify(e.json, null, 2)}</pre>
            {e.json.files.map((f) => (
              <div key={f.id} className="mt-1 font-mono text-[11px] text-amber-200">+ files/{e.uuid}/{f.id} ({f.name}, {f.size} B, {e.cat === 'DOCUMENT' ? 'document' : 'attachment'})</div>
            ))}
          </div>
          <div className="mt-2 font-mono text-[11px] text-neutral-400">
            sha256(items/{e.id}.json) = {digest ? `${digest.slice(0, 16)}…` : '…'}{' '}
            {digest && manRow && manRow[1] === digest ? <span className="text-emerald-400">= MANIFEST row ✓</span> : <span className="text-red-400">≠ MANIFEST</span>}
          </div>
        </div>

        <div className="text-center text-2xl text-neutral-600">↓</div>

        {/* 2. inside the encrypted archive */}
        <div>
          <div className="mb-2 text-xs font-bold uppercase tracking-wider text-neutral-300">2 · Inside vault.tar.gz (encrypted)</div>
          <pre className="overflow-auto rounded-lg border border-neutral-700 bg-neutral-900 p-2 font-mono text-[11px] leading-4">
            {listing.map((l, i) => (
              <div key={i} className={l.includes(e.uuid) ? 'text-amber-300' : 'text-neutral-400'}>{l.replace(/\s+/g, ' ')}</div>
            ))}
          </pre>
          <div className="mt-2 text-[11px] text-neutral-400">owner <span className="font-mono">nobody 0/0</span>, time <span className="font-mono">2000-01-01</span>, mode <span className="font-mono">0600</span>: no username or seal time inside (S2).</div>
          <div className="mt-2 rounded-lg border border-sky-500/50 bg-sky-500/5 p-2 font-mono text-[11px] leading-4 text-sky-200">
            <div className="text-sky-300">MANIFEST.csv (sealed copy)</div>
            <div className="break-all">{manRow ? manRow.join(',') : '—'}</div>
            {att.filter((r) => r[0] === e.uuid).length > 0 && <>
              <div className="mt-1 text-sky-300">ATTACHMENTS.csv</div>
              {att.filter((r) => r[0] === e.uuid).map((r) => <div key={r[1]} className="break-all">{r.join(',')}</div>)}
            </>}
          </div>
          <div className="mt-2 text-[11px] text-neutral-400">All 4 entries are archived together, compressed (gzip -n) and encrypted <b>once</b> with a fresh age X25519 data key.</div>
        </div>

        <div className="text-center text-2xl text-neutral-600">↓</div>

        {/* 3. the published payload */}
        <div>
          <div className="mb-2 flex items-center justify-between">
            <span className="text-xs font-bold uppercase tracking-wider text-neutral-300">3 · Published: SEALED.txt (self-contained)</span>
            <button onClick={() => setFull((v) => !v)} className="rounded border border-neutral-700 px-2 py-0.5 text-[11px] text-neutral-300 hover:bg-neutral-800">{full ? 'collapse armor' : 'show full armor'}</button>
          </div>
          <div className="space-y-1.5">
            {segs.map((sgm, i) => (
              <div key={i} className={`rounded-md border p-2 ${KIND[sgm.kind]} ${sgm.kind === 'vault' ? 'ring-2 ring-amber-400/70' : ''}`}>
                <div className="mb-1 flex items-center justify-between text-[10px] uppercase tracking-wider opacity-80">
                  <span>{sgm.label}</span>
                  {sgm.kind === 'vault' && <span className="text-amber-300" style={{ textTransform: 'none', letterSpacing: 'normal' }}>entry {e.id} is inside this block, with all the others</span>}
                </div>
                <pre className="overflow-auto whitespace-pre font-mono text-[10.5px] leading-[14px]">
                  {sgm.kind === 'time' || sgm.kind === 'vault' ? ArmorBlock({ lines: sgm.lines, full }) : sgm.lines.join('\n')}
                </pre>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="mt-3 flex flex-wrap gap-2 text-[11px]">
        <span className="rounded border border-neutral-700 px-2 py-0.5 text-neutral-300">Not published (stay local): MANIFEST.csv · BLANK-AT-SEAL.txt · README.txt · unlock-KEY.age (R44/R45)</span>
        <span className="rounded border border-neutral-700 px-2 py-0.5 text-neutral-300">Unlock round includes a random offset so it can't be traced back to the moment of sealing (S2)</span>
        <span className="rounded border border-neutral-700 px-2 py-0.5 text-neutral-300">Format as rehearsed for S2; the sealers will write it at seal time</span>
      </div>
    </section>
  )
}
